import{_ as r,a0 as n,w as l,s as o,ao as h,I as p,x as a,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"蘋果新的文件系統 APFS 比 HFS+ 強在哪裏？ | LCTT x X-CMD","titleTemplate":false,"description":"蘋果新的文件系統 APFS 比 HFS+ 強在哪裏？ | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"蘋果新的文件系統 APFS 比 HFS+ 強在哪裏？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"蘋果新的文件系統 APFS 比 HFS+ 強在哪裏？ | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161025 What is Apple File System and Why is it Better than HFS","title":"蘋果新的文件系統 APFS 比 HFS+ 強在哪裏？","tag":"201611","desc":""},"relativePath":"201611/20161025 What is Apple File System and Why is it Better than HFS.md","filePath":"[post].md"}'),d={name:"201611/20161025 What is Apple File System and Why is it Better than HFS.md"};function m(f,e,S,F,c,x){const t=n("Link");return l(),o("div",null,[e[13]||(e[13]=h('<h1 id="蘋果新的文件系統-apfs-比-hfs-強在哪裏" tabindex="-1">蘋果新的文件系統 APFS 比 HFS+ 強在哪裏？ <a class="header-anchor" href="#蘋果新的文件系統-apfs-比-hfs-強在哪裏" aria-label="Permalink to “蘋果新的文件系統 APFS 比 HFS+ 強在哪裏？”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/09/apple-file-system-hero-icon.jpg" alt="" title="What is Apple File System and Why is it Better than HFS+?s"></p><p>如果你一直關注蘋果最新版的 macOS 的消息，你可能已經注意到蘋果文件系統 APFS。這是不太讓人感冒的話題之一。然而，它是支撐了操作系統用户體驗的核心結構。APFS 將在 2017 年之前完成，不過你現在可以在 Sierra（最新版的 macOS） 上面體驗一番開發者預覽版。</p><h3 id="特色與改進" tabindex="-1">特色與改進 <a class="header-anchor" href="#特色與改進" aria-label="Permalink to “特色與改進”">​</a></h3><p>先快速科普一下，<strong>文件系統</strong>是操作系統用於存儲和檢索數據的基本結構，不同的文件系統採用不同的方式來實現這個任務。隨着計算機變得越來越快，新生代的文件系統已經從計算機速度的提升中獲益，以提供新功能和適應現代存儲需求。</p><p>HFS+，作為今天新一代 Mac 的附帶文件系統，已經 18 歲了。它的祖先 HFS 比 Tom Cruise 的兄弟情影片“壯志凌雲”還要老。它有點像一輛老豐田。它仍然可以工作（也許驚人的好），但是它不再得到人們的嘉獎。</p><p>APFS 不完全是 HFS+ 的升級版，因為相對現在而言，它是一個大幅度的飛躍。雖然這對蘋果用户來説是一個重大的升級，但似乎這看起來更像是蘋果趕上了其它系統，而不是超越了它們。然而，更新還進展得非常慢。</p><h3 id="克隆和數據完整性" tabindex="-1">克隆和數據完整性 <a class="header-anchor" href="#克隆和數據完整性" aria-label="Permalink to “克隆和數據完整性”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-cloning.png" alt="apfs-cloning" title="apfs-cloning"></p><p>APFS 使用稱為寫時複製（copy-on-write）的方案來生成重複文件的即時克隆。在 HFS+ 下，當用户複製文件的時候，每一個比特（二進制中的“位”）都會被複制。而 APFS 則通過操作元數據並分配磁盤空間來創建克隆。但是，在修改複製的文件之前都不會複製任何比特。當克隆體與原始副本分離的時候，那些改動（並且只有那些改動）才會被保存。</p><p>寫時複製還提高了數據的完整性。在其它系統下，如果你卸載卷導致覆寫操作掛起的話，你可能會發現你的文件系統有一部分與其它部分不同步。寫時複製則通過將改動寫入到可用的磁盤空間而不是覆蓋舊文件來避免這個問題。直到寫入操作成功完成前，舊文件都是正式版本。只有當新文件被成功複製時，舊文件才會被清除。</p><h3 id="系統快照" tabindex="-1">系統快照 <a class="header-anchor" href="#系統快照" aria-label="Permalink to “系統快照”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-snapshots.png" alt="apfs-snapshots" title="apfs-snapshots"></p><p>快照是寫時複製架構給你帶來的一個主要的升級。快照是文件系統在某個時間點的一個只讀的可裝載映像。隨着文件系統發生改動，只有改動的比特會被更改。這可以讓備份更簡單，更可靠。考慮到時間機器（一個蘋果出品的備份工具）已經成為硬鏈接的痛點，這可能是一個重大的升級。</p><h3 id="輸入-輸出的服務質量-qos" tabindex="-1">輸入/輸出的服務質量（QoS） <a class="header-anchor" href="#輸入-輸出的服務質量-qos" aria-label="Permalink to “輸入/輸出的服務質量（QoS）”">​</a></h3><p>你可能已經在你的路由器説明書看到了服務質量（QoS）這個名詞。QoS 優先分配帶寬使用以避免降低優先任務的速度。在你的路由器上，它採用用户定義的規則來為指定任務提供最大的帶寬。據報道，蘋果的 QoS 會優先考慮用户操作，例如活躍窗口。而諸如時間機器備份這些後台任務將會被降級。所以，這意味着更少的閒暇時光了？</p><h3 id="本地加密" tabindex="-1">本地加密 <a class="header-anchor" href="#本地加密" aria-label="Permalink to “本地加密”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-encryption-1.jpg" alt="apfs-encryption-1" title="apfs-encryption-1"></p><p>在後斯諾登時代，加密成為眾所關注的了。越來越多的蘋果產品正在強調其系統安全性。內置強大的加密機制並不讓人感到意外。包括 APFS 在內，蘋果正在採用更加細緻入微的加密方案，要麼不加密，要麼就將加密進行到底。用户可以使用單個密鑰來為所有數據加密，或者使用多個加密密鑰分別鎖定單個文件和文件夾。當然，你也可以不加密，只要你對壞蛋無所忌憚。</p><h3 id="固態硬盤和閃存優化" tabindex="-1">固態硬盤和閃存優化 <a class="header-anchor" href="#固態硬盤和閃存優化" aria-label="Permalink to “固態硬盤和閃存優化”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-ssd-storage.jpg" alt="apfs-ssd-storage" title="apfs-ssd-storage"></p><p>閃存優化已經被列為 APFS 的一個亮點功能，不過它的實現並沒有那麼振奮人心。蘋果選擇將一些典型的固態硬盤芯片的處理功能遷移到操作系統，而沒有深度系統集成的優勢。這更像是讓文件系統感知固態硬盤，而不是為它們做優化。</p><h3 id="動態分區調整" tabindex="-1">動態分區調整 <a class="header-anchor" href="#動態分區調整" aria-label="Permalink to “動態分區調整”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/apfs-partition-resizing.jpg" alt="apfs-partition-resizing" title="apfs-partition-resizing"></p><p>APFS 驅動器的邏輯分區可以動態調整自身大小。用户只需指定所需分區的數量，然後文件系統會在運行時進行磁盤分配。每個分區只佔用其用於存儲文件的磁盤空間。剩餘的磁盤空間會由任何分區獲取。這種設計很整潔，不過比起其它文件系統，這更像是元文件夾。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>這是否重要？對於開發者和高級用户來説真是棒極了。對於一般的 Mac 用户應該沒有太多的外部差異。雖然升級是重大的舉措，但仍然存在一些缺失的部分。本地壓縮顯然還沒有，對用户數據進行的校驗也沒有。當然，2017 年還沒到，一切皆有可能，讓我們拭目以待。</p><hr>',28)),p("p",null,[e[1]||(e[1]=a("via: ",-1)),s(t,{href:"https://www.maketecheasier.com/apple-file-system-better-than-hfs/"},{default:i(()=>[...e[0]||(e[0]=[a("https://www.maketecheasier.com/apple-file-system-better-than-hfs/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=a("作者：",-1)),s(t,{href:"https://www.maketecheasier.com/author/alexfox-2-2-2/"},{default:i(()=>[...e[2]||(e[2]=[a("Alexander Fox",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),s(t,{href:"https://github.com/OneNewLife"},{default:i(()=>[...e[3]||(e[3]=[a("OneNewLife",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=a("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const u=r(d,[["render",m]]);export{k as __pageData,u as default};
